#include <stdio.h>


int main(void)
{
    int visits = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            visits++;
        }
    }
    printf("%d\n", visits);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int steps = 0;
    for (int n = 16; n > 1; n /= 2) {
        steps++;
    }
    printf("%d\n", steps);
    return 0;
}
